//! Actions-only owner-source provenance and original shared journal regressions.
use super::*;
use n::{group_owner_only::OwnerOnlySource as Source,group_owner_only_test_support as support,relation_update_policy::RelationWriteGrant as Grant,user_entry_ownership::UserEntryBook};
const CURRENT:&[u8]=b"[username:fixture@fixture.invalid]";
struct Case{f:Fixture,source:Arc<Source>,book:Arc<UserEntryBook>}
fn setup(uri:&[u8])->Case{
    let mut f=installed();f.backend.close();let mut b=OfflineBackend::new(f.owner.clone());b.claim_common_transport().unwrap();b.bind_common_identity(b"AccountEntry").unwrap();let cfg=NativeReceiverConfig{direct_domains:None,invite_notifications:None,im_messages:Some(NativeImConfig{notification_timeout_ms:30000,receive_info:false,directory_queries:false})};let policy=NativeReceiverPolicy::capture(&cfg).unwrap().with_creation_properties(cpolicy()).unwrap();b.arm_native_receivers(NativeReceiverSetup::capture(policy,true,None).unwrap()).unwrap();f.scope=b.connection_scope();let l=b.prepare_login(login(),&[]).unwrap();b.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(l.call_id,&support::login_result()),0).unwrap();b.configure_native_receivers(7).unwrap();f.backend=b;
    f.temp.database.with_conn(group_create_store::enable_owner_only).unwrap();let cert=n::tls_engine::tests::Certificates::generate("IP:127.0.0.1");let router=n::netstream_runtime::tests::policy(&cert.root,12345);let r=support::reference(&f.owner,&f.scope,&router);let book=UserEntryBook::original(f.owner.clone(),f.scope.clone());let source=Source::original(&f.owner,&f.scope,&router,r,book.clone(),uri).unwrap();Case{f,source,book}
}
fn admission(c:&Case,nonce:&str,read:bool)->Result<IntentAdmission,&'static str>{let f=&c.f;let m=RelationMessage::capture_owner_only(&f.scope,&f.owner,c.source.clone(),"private-owner-only",2,&[],nonce,read,cpolicy())?;let cfg=Arc::new(f.temp.database.with_conn(|db|RelationConfiguration::capture(db,f.run.line_id(),1,Some(&f.scope)))?);RelationIntent::capture(f.temp.database.clone(),f.run.clone(),f.owner.clone(),f.scope.clone(),Arc::new(m),cfg,f.gate.clone(),Instant::now()+Duration::from_secs(30))}
fn prepared(c:&Case)->(Arc<RelationIntent>,Arc<RelationAction>,Arc<RelationPermit>){let f=&c.f;let IntentAdmission::Fresh(i)=admission(c,&"c".repeat(32),true).unwrap()else{panic!()};let grant=Grant::OwnerOnly(cpolicy());let PreparedRelation::Fresh(a)=i.bind(f.backend.captured_im_binding().unwrap(),f.backend.captured_relation_identity().unwrap(),grant).unwrap()else{panic!()};let p=a.permit(grant).unwrap();(i,a,p)}
#[test]fn owner_only_encodes_one_authenticated_uid_separate_parsed_first_and_empty_second_and_map(){let mut c=setup(CURRENT);let(_i,_a,p)=prepared(&c);let packet=write(&mut c.f,&p);let req=decode_request(&packet.packets[0].expose_to_transport()[1..]).unwrap();assert_eq!(req.method,b"createOrganize.GroupServer.Group");let mut r=Reader::versioned(req.arguments).unwrap();assert_eq!(r.u32().unwrap(),1);assert_eq!(r.bytes().unwrap(),support::UID);assert_eq!(r.u32().unwrap(),0);assert_eq!(r.bytes().unwrap(),b"fixture");assert!(r.bytes().unwrap().is_empty()&&r.properties().unwrap().is_empty());let props=r.properties().unwrap();assert_eq!(props.len(),2);assert!(props.iter().any(|p|p.key==b"Group.Org.Type"&&p.value==b"LargeGroup"));r.finish().unwrap();assert_eq!(state(&c.f),(0,Some(2),None,None));p.cancel();}
#[test]fn owner_only_actor_checks_entire_original_uri_before_allocating_any_request_id(){for wrong in [b"[username:fixture@other.invalid]".as_slice(),b"[username:another@fixture.invalid]"]{let mut c=setup(wrong);let(_i,a,p)=prepared(&c);assert!(c.f.backend.prepare_relation_update(p.clone(),Instant::now()+Duration::from_secs(2)).is_err());assert_eq!(state(&c.f),(0,None,None,None));a.cancel();assert_eq!(state(&c.f).0,3);let read=c.f.backend.prepare_im_read(Arc::new(ImQuery::refresh(&[],-1).unwrap()),c.f.gate.clone(),Instant::now()+Duration::from_secs(2)).unwrap();assert_eq!(read.call_id,2);}}
#[test]fn owner_only_source_rejects_foreign_router_book_scope_and_malformed_id_source(){let c=setup(CURRENT);let f=&c.f;let cert=n::tls_engine::tests::Certificates::generate("IP:127.0.0.1");let router=n::netstream_runtime::tests::policy(&cert.root,1);let other=n::netstream_runtime::tests::policy(&cert.root,1);let r=support::reference(&f.owner,&f.scope,&router);let scope=RpcConnectionScope::fresh();assert!(Source::original(&f.owner,&f.scope,&other,r.clone(),c.book.clone(),CURRENT).is_err());assert!(Source::original(&f.owner,&scope,&router,r.clone(),c.book.clone(),CURRENT).is_err());assert!(Source::original(&f.owner,&f.scope,&router,r.clone(),UserEntryBook::original(f.owner.clone(),scope),CURRENT).is_err());for uri in [b"".as_slice(),b"+12345",b"[phone:+12345@nodot]",b"fixture-account"]{assert!(Source::original(&f.owner,&f.scope,&router,r.clone(),c.book.clone(),uri).is_err());}assert!(c.source.arguments(b"opaque-uid",&[0,0,0,0,0]).is_err());}
#[test]fn owner_only_uses_same_nonce_preparing_and_distinct_grant_from_explicit_creation(){let c=setup(CURRENT);let IntentAdmission::Fresh(i)=admission(&c,&"c".repeat(32),true).unwrap()else{panic!()};assert_eq!(prep(&c.f,&"c".repeat(32),b"fixture-user",true).err(),Some("app_account_relation_nonce_conflict"));assert_eq!(prep(&c.f,&"d".repeat(32),b"fixture-user",true).err(),Some("app_account_relation_preparing"));assert!(i.bind(c.f.backend.captured_im_binding().unwrap(),c.f.backend.captured_relation_identity().unwrap(),cpolicy()).is_err());drop(i);let IntentAdmission::Fresh(exp)=prep(&c.f,&"e".repeat(32),b"fixture-user",true).unwrap()else{panic!()};assert!(exp.bind(c.f.backend.captured_im_binding().unwrap(),c.f.backend.captured_relation_identity().unwrap(),Grant::OwnerOnly(cpolicy())).is_err());}
#[test]fn owner_only_book_retirement_revokes_physical_guard_and_actual_packet_holds_budget_to_last_drop(){let mut c=setup(CURRENT);let(i,a,p)=prepared(&c);let packet=write(&mut c.f,&p).packets.pop().unwrap();assert!(packet.group_event_packet_current(Instant::now()));c.book.retire();assert!(!packet.group_event_packet_current(Instant::now()));assert!(!p.begin_write(2));c.f.backend.close();drop(p);drop(a);drop(i);drop(c.source);assert!(c.f.scope.native_rpc_resources().0>0);drop(packet);assert_eq!(c.f.scope.native_rpc_resources(),(0,0));}
#[test]fn owner_only_descriptor_integrity_guards_io_and_old_mode_cannot_consume_a_result(){let mut c=setup(CURRENT);let(_i,_a,p)=prepared(&c);let packet=write(&mut c.f,&p);let db=&c.f.temp.database;assert!(db.with_conn(|conn|conn.execute("UPDATE app_voice_group_creations SET owner_only=0",[]).map_err(|_|"constraint")).is_err());assert!(db.with_conn(|conn|conn.execute("UPDATE app_voice_group_creations SET owner_only=0,owner_only_hash=NULL",[]).map_err(|_|"immutable")).is_err());db.with_conn(|conn|conn.execute_batch("DROP TRIGGER app_voice_owner_mode_immutable; UPDATE app_voice_group_creations SET owner_only=0,owner_only_hash=NULL;").map_err(|_|"fixture corrupt storage")).unwrap();assert!(!packet.packets[0].group_event_packet_current(Instant::now()));assert!(!p.begin_write(packet.call_id));assert_eq!(state(&c.f).0,0);assert!(admission(&c,&"b".repeat(32),true).is_err());}
#[test]fn owner_only_committed_read_brand_is_private_and_book_retirement_does_not_undo_write(){let mut c=setup(CURRENT);let(_i,_a,p)=prepared(&c);let f=&mut c.f;let packet=write(f,&p);assert!(p.begin_write(packet.call_id));assert!(p.submitted());f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(packet.call_id,&result(true,GROUP,b"")),0).unwrap();let r=f.backend.take_relation_replies().pop().unwrap();let v=p.resolve(&r).unwrap();assert_eq!(v.management.as_ref().unwrap().operation,"create_owner_only");let receipt=v.creation_receipt.unwrap();assert!(receipt.current());c.book.retire();assert!(!receipt.current());assert_eq!(state(f).0,1);let history=f.temp.database.with_conn(|db|n::relation_journal::history(db,f.run.line_id(),128)).unwrap();assert_eq!(history[0].state,"confirmed");assert!(history[0].creation_receipt.is_none());}
#[test]fn owner_only_source_bounded_even_with_detached_reference_and_budget_exhaustion(){let c=setup(CURRENT);let f=&c.f;let cert=n::tls_engine::tests::Certificates::generate("IP:127.0.0.1");let router=n::netstream_runtime::tests::policy(&cert.root,1);let r=support::reference(&f.owner,&f.scope,&router);let before=f.scope.native_rpc_resources();let full=f.scope.reserve_native_rpc(n::rpc_stream::MAX_STREAM_BYTES-before.1).unwrap();assert!(Source::original(&f.owner,&f.scope,&router,r,c.book.clone(),CURRENT).is_err());drop(full);assert_eq!(f.scope.native_rpc_resources(),before);assert!(!format!("{:?}",c.source).contains("fixture"));}
